import React, { useEffect, useState } from 'react';
import './Loading.css'; // Update the CSS file for styling

const Loading = () => {
  const [showMessage, setShowMessage] = useState(true);

  useEffect(() => {
    const timer = setTimeout(() => {
      setShowMessage(false); // Hide message after 3 seconds
    }, 3000); // Adjust the duration to your preference
    return () => clearTimeout(timer); // Cleanup timer on component unmount
  }, []);

  return (
    <div className="loading-container">
      <div className="spinner"></div> {/* Spinner for loading effect */}
      {showMessage && <div className="new-year-message">Happy New Year!</div>}
    </div>
  );
};

export default Loading;

